return items.map(item => {
  const deal = item.json;

  return {
    json: {
      record_type: "Deal",
      zoho_record_id: deal.id || null,

      deal_name: deal.Deal_Name || null,
      company_name: deal.Account_Name?.name || null,

      contact_name: deal.Contact_Name?.name || null,
      contact_id: deal.Contact_Name?.id || null,
      contact_email: deal.Contact_Name?.email || null,

      stage: deal.Stage || null,
      deal_value: deal.Amount || 0,
      probability: deal.Probability || null,

      owner: deal.Owner?.name || deal.Deal_Owner?.name || deal.Created_By?.name || null,
      owner_email: deal.Owner?.email || deal.Deal_Owner?.email || deal.Created_By?.email || null,

      last_follow_up_date: deal.Last_Follow_Up_Date || null,
      closing_date: deal.Closing_Date || null,

      modified_time: deal.Modified_Time || null,
      created_time: deal.Created_Time || null,

      source_module: "Deals"
    }
  };
});

const staleRules = {
  "Qualification": 2,
  "Needs Analysis": 3,
  "Proposal/Price Quote": 5,
  "Negotiation/Review": 2,
  "Value Proposition": 5,
  "Identify Decision Makers": 5
};

return items.map(item => {
  const deal = item.json;

  const today = new Date();
  const lastFollowUpDate = deal.last_follow_up_date
    ? new Date(deal.last_follow_up_date)
    : null;

  let daysInactive = null;
  let staleAfterDays = staleRules[deal.stage] ?? null;
  let isStale = false;

  if (lastFollowUpDate && staleAfterDays !== null) {
    const diffMs = today - lastFollowUpDate;
    daysInactive = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    isStale = daysInactive >= staleAfterDays;
  }

  return {
    json: {
      ...deal,
      days_inactive: daysInactive,
      stale_after_days: staleAfterDays,
      is_stale: isStale
    }
  };
});

