parameters.jsCode:
return items.map(item => {
  const rawOutput = item.json.output || "";

  let cleaned = rawOutput.trim();

  // Remove <think>...</think> blocks if the model outputs reasoning
  cleaned = cleaned.replace(/<think>[\s\S]*?<\/think>/gi, "").trim();

  // Remove markdown code fences if present
  cleaned = cleaned
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();

  // Extract the first JSON object from the remaining text
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);

  if (!jsonMatch) {
    throw new Error(`No JSON object found in AI output: ${rawOutput}`);
  }

  let parsed;

  try {
    parsed = JSON.parse(jsonMatch[0]);
  } catch (error) {
    throw new Error(`AI returned invalid JSON after cleaning: ${jsonMatch[0]}`);
  }

  const requiredFields = [
    "risk_level",
    "reason",
    "recommended_action",
    "follow_up_subject",
    "follow_up_email",
    "crm_task_title",
    "crm_task_description"
  ];

  for (const field of requiredFields) {
    if (!(field in parsed)) {
      throw new Error(`Missing required AI field: ${field}`);
    }
  }

  return {
    json: {
      ...item.json,

      ai_risk_level: parsed.risk_level,
      ai_reason: parsed.reason,
      ai_suggested_action: parsed.recommended_action,
      follow_up_subject: parsed.follow_up_subject,
      follow_up_email: parsed.follow_up_email,
      crm_task_title: parsed.crm_task_title,
      crm_task_description: parsed.crm_task_description
    }
  };
});

